/* LiquidPay service worker — generated by scripts/build-sw.mjs. Do not edit out/sw.js.
 *
 * The whole app is precached on install, so after one visit it opens and works
 * with no internet: the offline payment rails (123Pay calls, *99#) need none.
 * Strategy: cache-first for everything we built; new deploys ship a new VERSION,
 * which installs in the background and takes over on the next launch.
 */
const VERSION = "__VERSION__";
const PRECACHE = __PRECACHE__;
const CACHE = `liquidpay-${VERSION}`;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((c) => c.addAll(PRECACHE.map((u) => new Request(u, { cache: "reload" }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("liquidpay-") && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

/** /pay/ → /pay, so a trailing slash still hits the precached page. */
function normalize(url) {
  const u = new URL(url);
  if (u.pathname.length > 1 && u.pathname.endsWith("/")) u.pathname = u.pathname.slice(0, -1);
  u.search = "";
  return u.toString();
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      const hit = await cache.match(normalize(req.url), { ignoreSearch: true });
      if (hit) return hit;
      try {
        const res = await fetch(req);
        if (res.ok && res.type === "basic") cache.put(normalize(req.url), res.clone());
        return res;
      } catch {
        // Offline and not cached: fall back to the app shell for page loads.
        if (req.mode === "navigate") return (await cache.match(new URL("/", self.location.origin).toString())) ?? Response.error();
        return Response.error();
      }
    })(),
  );
});
